4310:     fn block_actions_reconcile_rejections_confirm_commits_and_isolate_late_results() {
4311:         struct BlockBackend {
4312:             action: std::sync::Mutex<Option<crate::module_bindings::GatewayBlockAction>>,
4313:             state: std::sync::Mutex<i32>,
4314:             revision: std::sync::Mutex<u64>,
4315:             results: std::sync::Mutex<Vec<std::sync::mpsc::Sender<io::Result<()>>>>,
4316:             submits: std::sync::atomic::AtomicUsize,
4317:         }
4318:         impl BlockBackend {
4319:             fn new() -> Self {
4320:                 Self {
4321:                     action: std::sync::Mutex::new(None),
4322:                     state: std::sync::Mutex::new(1),
4323:                     revision: std::sync::Mutex::new(1),
4324:                     results: std::sync::Mutex::new(Vec::new()),
4325:                     submits: std::sync::atomic::AtomicUsize::new(0),
4326:                 }
4327:             }
4328: 
4329:             fn publish_action(&self, session_uuid: uuid::Uuid, state: i32, sequence: u64) {
4330:                 *self.state.lock().unwrap() = state;
4331:                 *self.revision.lock().unwrap() = sequence + 1;
4332:                 *self.action.lock().unwrap() = Some(crate::module_bindings::GatewayBlockAction {
4333:                     session_uuid: spacetimedb_sdk::Uuid::from_u128(session_uuid.as_u128()),
4334:                     sequence,
4335:                     x: 8,
4336:                     y: 63,
4337:                     z: 8,
4338:                     expected_state: 1,
4339:                     resulting_state: state as u32,
4340:                     revision: sequence + 1,
4341:                 });
4342:             }
4343:         }
4344:         impl SessionStore for BlockBackend {
4345:             fn begin(&self, _: uuid::Uuid, _: &str) -> io::Result<()> {
4346:                 Ok(())
4347:             }
4348:             fn configure(&self, _: uuid::Uuid) -> io::Result<i32> {
4349:                 Ok(16384)
4350:             }
4351:             fn play(&self, _: uuid::Uuid) -> io::Result<()> {
4352:                 Ok(())
4353:             }
4354:             fn chunk_snapshot(
4355:                 &self,
4356:                 _: uuid::Uuid,
4357:                 chunk_x: i32,
4358:                 chunk_z: i32,
4359:             ) -> io::Result<Option<crate::module_bindings::GatewayChunkSnapshot>> {
4360:                 let mut encoded_overrides = Vec::new();
4361:                 if (chunk_x, chunk_z) == (0, 0) {
4362:                     for value in [8_i32, 63, 8, *self.state.lock().unwrap()] {
4363:                         encoded_overrides.extend(value.to_le_bytes());
4364:                     }
4365:                 }
4366:                 Ok(Some(crate::module_bindings::GatewayChunkSnapshot {
4367:                     snapshot_key: format!("{chunk_x}:{chunk_z}"),
4368:                     world_id: "test".into(),
4369:                     chunk_x,
4370:                     chunk_z,
4371:                     encoded_overrides,
4372:                     revision: *self.revision.lock().unwrap(),
4373:                 }))
4374:             }
4375:             fn requires_persistent_world_snapshots(&self) -> bool {
4376:                 true
4377:             }
4378:             fn block_action_submit(
4379:                 &self,
4380:                 _: uuid::Uuid,
4381:                 _: u64,
4382:                 _: i32,
4383:                 _: i32,
4384:                 _: i32,
4385:                 _: u32,
4386:                 _: bool,
4387:             ) -> io::Result<std::sync::mpsc::Receiver<io::Result<()>>> {
4388:                 self.submits
4389:                     .fetch_add(1, std::sync::atomic::Ordering::SeqCst);
4390:                 let (sender, receiver) = std::sync::mpsc::channel();
4391:                 self.results.lock().unwrap().push(sender);
4392:                 Ok(receiver)
4393:             }
4394:             fn block_action_snapshot(
4395:                 &self,
4396:                 session: uuid::Uuid,
4397:             ) -> io::Result<Option<crate::module_bindings::GatewayBlockAction>> {
4398:                 Ok(self
4399:                     .action
4400:                     .lock()
4401:                     .unwrap()
4402:                     .clone()
4403:                     .filter(|action| action.session_uuid.as_u128() == session.as_u128()))
4404:             }
4405:             fn end(&self, _: uuid::Uuid) {}
4406:         }
