4408:         let backend = Arc::new(BlockBackend::new());
4409:         let position = play::BlockPosition { x: 8, y: 63, z: 8 };
4410:         let mut session = initialized_m1(backend.clone());
4411:         session
4412:             .receive(
4413:                 &[pending_ack(&session), play_frame(0x2c, &[])].concat(),
4414:                 &mut Vec::new(),
4415:             )
4416:             .unwrap();
4417:         let session_id = session.backend_session.unwrap();
4418:         let mut output = Vec::new();
4419: 
4420:         // One pending reducer call is permitted; a second prediction is corrected and ACKed.
4421:         session
4422:             .queue_block_action(1, position, false, &mut output)
4423:             .unwrap();
4424:         assert!(output.is_empty());
4425:         session
4426:             .queue_block_action(2, position, false, &mut output)
4427:             .unwrap();
4428:         assert_eq!(backend.submits.load(std::sync::atomic::Ordering::SeqCst), 1);
4429:         assert_eq!(packet_ids(&output), vec![0x08, 0x04]);
4430:         assert_eq!(session.block_sequence, 0);
4431: 
4432:         // A subscribed commit row alone is insufficient until reducer callback success arrives.
4433:         backend.publish_action(session_id, 0, 1);
4434:         output.clear();
4435:         session
4436:             .poll_block_action(Instant::now(), &mut output)
4437:             .unwrap();
4438:         assert!(output.is_empty());
4439:         backend.results.lock().unwrap()[0].send(Ok(())).unwrap();
4440:         session
4441:             .poll_block_action(Instant::now(), &mut output)
4442:             .unwrap();
4443:         assert_eq!(packet_ids(&output), vec![0x08, 0x04]);
4444:         assert_eq!(session.block_sequence, 1);
4445: 
4446:         // A rejected callback reconciles the authoritative old block before prediction ACK.
4447:         backend.publish_action(session_id, 0, 1);
4448:         output.clear();
4449:         session
4450:             .queue_block_action(3, position, false, &mut output)
4451:             .unwrap();
4452:         backend.results.lock().unwrap()[1]
4453:             .send(Err(io::Error::other("rejected")))
4454:             .unwrap();
4455:         session
4456:             .poll_block_action(Instant::now(), &mut output)
4457:             .unwrap();
4458:         assert_eq!(packet_ids(&output), vec![0x08, 0x04]);
4459:         assert_eq!(session.block_sequence, 1);
4460: 
4461:         // Disconnect clears pending work; a late callback from that session cannot affect its replacement.
4462:         output.clear();
4463:         session
4464:             .queue_block_action(4, position, false, &mut output)
4465:             .unwrap();
4466:         let late_sender = backend.results.lock().unwrap()[2].clone();
4467:         let old_session = session.backend_session.unwrap();
4468:         session
4469:             .disconnect_play(&mut output, "test replacement")
4470:             .unwrap();
4471:         let mut replacement = initialized_m1(backend.clone());
4472:         replacement
4473:             .receive(
4474:                 &[pending_ack(&replacement), play_frame(0x2c, &[])].concat(),
4475:                 &mut Vec::new(),
4476:             )
4477:             .unwrap();
4478:         assert_ne!(replacement.backend_session.unwrap(), old_session);
4479:         assert!(late_sender.send(Ok(())).is_err());
4480:         output.clear();
4481:         replacement
4482:             .poll_block_action(Instant::now(), &mut output)
4483:             .unwrap();
4484:         assert!(output.is_empty());
4485:         assert_eq!(replacement.block_sequence, 0);
4486:         assert!(replacement.block_pending.is_none());
4487: 
4488:         replacement
4489:             .queue_block_action(5, position, false, &mut output)
4490:             .unwrap();
4491:         let deadline = replacement.block_pending.as_ref().unwrap().deadline;
4492:         replacement
4493:             .poll_block_action(deadline, &mut output)
4494:             .unwrap();
4495:         assert_eq!(replacement.state, ConnectionState::Closed);
4496:         assert!(replacement.block_pending.is_none());
4497:     }
