4888:     fn chunk_load_reconciles_snapshot_changes_during_and_after_batch_emission() {
4889:         struct SnapshotRaceBackend {
4890:             reads: std::sync::Mutex<std::collections::HashMap<(i32, i32), usize>>,
4891:         }
4892:         impl SessionStore for SnapshotRaceBackend {
4893:             fn begin(&self, _: uuid::Uuid, _: &str) -> io::Result<()> {
4894:                 Ok(())
4895:             }
4896:             fn configure(&self, _: uuid::Uuid) -> io::Result<i32> {
4897:                 Ok(16384)
4898:             }
4899:             fn play(&self, _: uuid::Uuid) -> io::Result<()> {
4900:                 Ok(())
4901:             }
4902:             fn chunk_snapshot(
4903:                 &self,
4904:                 _: uuid::Uuid,
4905:                 chunk_x: i32,
4906:                 chunk_z: i32,
4907:             ) -> io::Result<Option<crate::module_bindings::GatewayChunkSnapshot>> {
4908:                 let read = {
4909:                     let mut reads = self.reads.lock().unwrap();
4910:                     let read = reads.entry((chunk_x, chunk_z)).or_default();
4911:                     *read += 1;
4912:                     *read
4913:                 };
4914:                 let mut encoded_overrides = Vec::new();
4915:                 let revision = if (chunk_x, chunk_z) == (0, 0) && read > 1 {
4916:                     let state = if read > 2 { 1 } else { 0 };
4917:                     for value in [8_i32, 63, 8, state] {
4918:                         encoded_overrides.extend(value.to_le_bytes());
4919:                     }
4920:                     if read > 2 {
4921:                         3
4922:                     } else {
4923:                         2
4924:                     }
4925:                 } else {
4926:                     1
4927:                 };
4928:                 Ok(Some(crate::module_bindings::GatewayChunkSnapshot {
4929:                     snapshot_key: format!("{chunk_x}:{chunk_z}"),
4930:                     world_id: "test".into(),
4931:                     chunk_x,
4932:                     chunk_z,
4933:                     encoded_overrides,
4934:                     revision,
4935:                 }))
4936:             }
4937:             fn requires_persistent_world_snapshots(&self) -> bool {
4938:                 true
4939:             }
4940:             fn end(&self, _: uuid::Uuid) {}
4941:         }
4942: 
4943:         let backend = Arc::new(SnapshotRaceBackend {
4944:             reads: std::sync::Mutex::new(std::collections::HashMap::new()),
4945:         });
4946:         let mut session = initialized_m1(backend.clone());
4947:         session
4948:             .receive(
4949:                 &[pending_ack(&session), play_frame(0x2c, &[])].concat(),
4950:                 &mut Vec::new(),
4951:             )
4952:             .unwrap();
4953:         backend.reads.lock().unwrap().clear();
4954:         session.loaded_chunks.clear();
4955:         session.chunk_revisions.clear();
4956:         session.pending_chunk_center = Some((0, 0));
4957:         session.next_chunk_batch = Instant::now();
4958: 
4959:         let mut output = Vec::new();
4960:         session.poll(Instant::now(), &mut output).unwrap();
4961:         let mut packets = Vec::new();
4962:         let mut remaining = output.as_slice();
4963:         while let Some((packet, consumed)) = parse_packet(remaining, None, false).unwrap() {
4964:             packets.push(packet);
4965:             remaining = &remaining[consumed..];
4966:         }
4967:         let last_chunk = packets
4968:             .iter()
4969:             .rposition(|packet| packet.id == i32::from(play::CHUNK))
4970:             .unwrap();
4971:         let block_update = packets.iter().position(|packet| packet.id == 0x08).unwrap();
4972:         let batch_finished = packets
4973:             .iter()
4974:             .position(|packet| packet.id == i32::from(play::BATCH_END))
4975:             .unwrap();
4976:         let mut expected = Vec::new();
4977:         play::Clientbound::BlockUpdate(play::BlockPosition { x: 8, y: 63, z: 8 }, 0)
4978:             .write(&mut expected)
4979:             .unwrap();
4980:         let (expected, _) = parse_packet(&expected, None, false).unwrap().unwrap();
4981:         assert!(last_chunk < block_update && block_update < batch_finished);
4982:         assert_eq!(packets[block_update].data, expected.data);
4983:         assert_eq!(session.chunk_revisions.get(&(0, 0)), Some(&2));
4984: 
4985:         // A later concurrent edit is picked up on the next Play poll, after
4986:         // the original chunk batch has already completed.
4987:         output.clear();
4988:         session
4989:             .poll(Instant::now() + SERVER_TICK, &mut output)
4990:             .unwrap();
4991:         let (later_update, _) = parse_packet(&output, None, false).unwrap().unwrap();
4992:         let mut expected = Vec::new();
4993:         play::Clientbound::BlockUpdate(play::BlockPosition { x: 8, y: 63, z: 8 }, 1)
4994:             .write(&mut expected)
4995:             .unwrap();
4996:         let (expected, _) = parse_packet(&expected, None, false).unwrap().unwrap();
4997:         assert_eq!(later_update.id, 0x08);
4998:         assert_eq!(later_update.data, expected.data);
4999:         assert_eq!(session.chunk_revisions.get(&(0, 0)), Some(&3));
